local app = select(2,...);

app.devMode = false;
app.devModeNoisy = false;
app.devColor = false;

local LookupAppIDNew = {}
local count;
local LookupSetIDNew;
local LookupSetIDAddition;
local setCount;
local setAddCount;

if app.devColor then
  app.devColorCount = {}
  for i=1,GetClientDisplayExpansionLevel() + 1 do
    app.devColorCount[i]=0;
  end
end
----
--
----
--For Filling in the Table
if app.devMode then  
  count = 0;
  LookupSetIDNew = {}
  LookupSetIDAddition = {}
  setCount = 0;
  setAddCount = 0;
  app.setIDFiller = {};

  local LookupBox = CreateFrame("EditBox", nil);
    LookupBox:SetPoint("CENTER", 300, -20);
    LookupBox:SetSize(300,25);
    LookupBox.tex = LookupBox:CreateTexture(nil, "BACKGROUND");
    LookupBox.tex:SetAllPoints(LookupBox);
    LookupBox.tex:SetColorTexture(.1,.1,.1,.75);
    
    LookupBox:SetNumber(0);
    LookupBox:SetAutoFocus(false);
    LookupBox:SetFontObject("GameFontNormal");
    LookupBox:SetJustifyH("CENTER");
    LookupBox:SetShown(false);
    
  local outputNew = CreateFrame("Button", nil);
    outputNew:SetPoint("CENTER", 0, -20);
    outputNew:SetSize(100,25);
    outputNew.tex = outputNew:CreateTexture(nil, "BACKGROUND");
    outputNew.tex:SetAllPoints(outputNew);
    outputNew.tex:SetColorTexture(.1,.1,.1,.75);
    outputNew:SetScript("OnClick", function(self, button)
        local text = "";
        for a,b in pairs(LookupAppIDNew) do
          text = text.."["..a.."]="..b..",";
        end
        LookupBox:SetText(text);
      end);
    outputNew:SetNormalFontObject("GameFontNormal");
    outputNew:SetText("Output New App IDs");
    outputNew:SetShown(false);
    
  local LookupBox2 = CreateFrame("EditBox", nil);
    LookupBox2:SetPoint("TOPLEFT", LookupBox, "BOTTOMLEFT", 0, -20);
    LookupBox2:SetSize(300,25);
    LookupBox2.tex = LookupBox2:CreateTexture(nil, "BACKGROUND");
    LookupBox2.tex:SetAllPoints(LookupBox2);
    LookupBox2.tex:SetColorTexture(.1,.1,.1,.75);
    
    LookupBox2:SetNumber(0);
    LookupBox2:SetAutoFocus(false);
    LookupBox2:SetFontObject("GameFontNormal");
    LookupBox2:SetJustifyH("CENTER");
    LookupBox2:SetShown(false);
    
  local outputNew2 = CreateFrame("Button", nil);
    outputNew2:SetPoint("TOPLEFT", outputNew, "BOTTOMLEFT", 0, -20);
    outputNew2:SetSize(100,25);
    outputNew2.tex = outputNew2:CreateTexture(nil, "BACKGROUND");
    outputNew2.tex:SetAllPoints(outputNew2);
    outputNew2.tex:SetColorTexture(.1,.1,.1,.75);
    outputNew2:SetScript("OnClick", function(self, button)
        local text = "";
        local loopCount = 0;
        for a,b in pairs(LookupSetIDNew) do
          text = text.."["..a.."]={"
          for c,d in pairs(b) do
            if type(d) == "table" then
              text = text.."{"
              for e,f in pairs(d) do
                text = text..tostring(f)..",";
              end
              text = text.."},"
            else
              text = text..tostring(d)..",";
            end
          end
          text = text.."},";
          loopCount = loopCount + 1;
          if loopCount >= 5000 then break; end
        end
        LookupBox2:SetText(text);
      end);
    outputNew2:SetNormalFontObject("GameFontNormal");
    outputNew2:SetText("Output New Set IDs");
    outputNew2:SetShown(false);
    
  local LookupBox3 = CreateFrame("EditBox", nil);
    LookupBox3:SetPoint("TOPLEFT", LookupBox2, "BOTTOMLEFT", 0, -20);
    LookupBox3:SetSize(300,25);
    LookupBox3.tex = LookupBox3:CreateTexture(nil, "BACKGROUND");
    LookupBox3.tex:SetAllPoints(LookupBox3);
    LookupBox3.tex:SetColorTexture(.1,.1,.1,.75);
    
    LookupBox3:SetNumber(0);
    LookupBox3:SetAutoFocus(false);
    LookupBox3:SetFontObject("GameFontNormal");
    LookupBox3:SetJustifyH("CENTER");
    LookupBox3:SetShown(false);
    
  local outputNew3 = CreateFrame("Button", nil);
    outputNew3:SetPoint("TOPLEFT", outputNew2, "BOTTOMLEFT", 0, -20);
    outputNew3:SetSize(100,25);
    outputNew3.tex = outputNew3:CreateTexture(nil, "BACKGROUND");
    outputNew3.tex:SetAllPoints(outputNew3);
    outputNew3.tex:SetColorTexture(.1,.1,.1,.75);
    outputNew3:SetScript("OnClick", function(self, button)
        local text = "";
        for a,b in pairs(app.setIDFiller) do
          text = text.."["..b.."]=true,\n";
        end
        LookupBox3:SetText(text);
        app.setIDFiller = {}
      end);
    outputNew3:SetNormalFontObject("GameFontNormal");
    outputNew3:SetText("Output Clicked SetIDs");
    outputNew3:SetShown(false);
    
  SLASH_EXS1 = '/exsdev';
  function SlashCmdList.EXS(msg, editbox)
    if LookupBox:IsShown() == false then
      LookupBox:SetShown(true);
      outputNew:SetShown(true);
      LookupBox2:SetShown(true);
      outputNew2:SetShown(true);
      LookupBox3:SetShown(true);
      outputNew3:SetShown(true);
    else
      LookupBox:SetShown(false);
      outputNew:SetShown(false);
      LookupBox2:SetShown(false);
      outputNew2:SetShown(false);
      LookupBox3:SetShown(false);
      outputNew3:SetShown(false);
    end
  end
end
