local GetSourceInfo = C_TransmogCollection.GetSourceInfo;

----
--
----
local function AppID(sourceID, setID, isArmor)
  if not app.devMode then
    if LookupAppID[sourceID] then
      return LookupAppID[sourceID];
    end
    if LookupAppIDNew[sourceID] then
      return LookupAppIDNew[sourceID], LookupSetID[LookupAppIDNew[sourceID]] == nil;
    end
    local sI = GetSourceInfo(sourceID);
    if not sI then return; end
    local appID = sI.visualID;
    LookupAppIDNew[sourceID] = appID;
    return appID, LookupSetID[appID] == nil;
  else
    local appID = LookupAppID[sourceID];
    if LookupAppIDNew[sourceID] then appID = LookupAppIDNew[sourceID] end
    if not appID then
      local sI = GetSourceInfo(sourceID);
      if not sI then if app.devMode then print("sourceInfo not found for ID: ",sourceID,"   set: ",setID) end return; end
      appID = sI.visualID;
      LookupAppIDNew[sourceID] = appID;
      count = count + 1;
      print("ExS App ID inc: ",count,"    with sourceID: ",sourceID,"    appID: ",appID);
    end
    local notInTable = LookupSetID[appID] == nil;
    
    if setID then 
      if not LookupSetID[appID] then
        LookupSetID[appID] = { isArmor, {setID}, }
        LookupSetIDNew[appID] = LookupSetID[appID]
        setCount = setCount + 1;
        print("ExS Set ID inc: ",setCount,"    with setID: ",setID,"    appID: ",appID);
      else
        local addSetID = true;
        for i=1,#LookupSetID[appID][2] do
          if LookupSetID[appID][2][i] == setID then
            addSetID = false;
            break;
          end
        end
        if addSetID then
          tinsert(LookupSetID[appID][2], setID);
          if LookupSetIDNew[appID] then
            local addID = true;
            for i=1,#LookupSetIDNew[appID][2] do
              if LookupSetIDNew[appID][2][i] == setID then
                addID = false;
                break;
              end
            end
            if addID then
              tinsert(LookupSetIDNew[appID][2], setID);
            end
          else
            LookupSetIDAddition[appID] = setID
            setAddCount = setAddCount + 1;
            print("ExS Set ID Addtion: ",setAddCount,"    with setID: ",setID,"    appID: ",appID);
          end
        end
      end
    end
    return appID, notInTable;
  end
end
app.AppID = AppID;

----
--returns the setIDs, isArmor
----
local function FindSetIDBySourceID(sourceID)
  local appID = AppID(sourceID);
  if LookupSetID[appID] then
    return LookupSetID[appID][2], LookupSetID[appID][1];
  else
    return nil;
  end
end
app.FindSetIDBySourceID = FindSetIDBySourceID;
FindSetIDBySourceIDGlobal = nil;
if app.devMode then FindSetIDBySourceIDGlobal = FindSetIDBySourceID end

----
--returns the setIDs, isArmor
----
local function FindSetIDByAppID(appID)
  if LookupSetID[appID] then
    return LookupSetID[appID][2], LookupSetID[appID][1];
  else
    return nil;
  end
end
app.FindSetIDByAppID = FindSetIDByAppID;

----
--
----
local function GetExSetSourcesFromSetID(longSetID, isWeapon)
  local expac, setID;
  if not isWeapon then
    expac = floor(longSetID/app.expandedID);
    setID = mod(longSetID,app.expandedID);
    local callback = app.GetExpacArmorSetSourcesBySetID[expac]
    return type(callback) == "function" and callback(setID) or {};
  else
    expac = floor(longSetID/1000);
    setID = mod(longSetID,1000);
    local callback = app.GetExpacWepSetSourcesBySetID[expac]
    return type(callback) == "function" and callback(setID) or {};
  end
end
app.GetExSetSourcesFromSetID = GetExSetSourcesFromSetID;

----
--
----
local function GetExSetInfoFromSetID(longSetID, isWeapon)
  local label, name, armorWeight;
  if not isWeapon then
    local expac = floor(longSetID/app.expandedID);
    local setID = mod(longSetID,app.expandedID);
    
    local callback = app.GetExpacArmorSetNameBySetID[expac]
    if type(callback) ~= "function" then return nil, nil, nil end
    label, name, armorWeight = callback(setID);
  else
    local expac = floor(longSetID/1000);
    local setID = mod(longSetID,1000);
    
    local callback = app.GetExpacWepSetNameBySetID[expac]
    if type(callback) ~= "function" then return nil, nil, nil end
    label, name = callback(setID);
  end
  if app.localized and app.localized[label] then label = app.localized[label] end
  if app.localized and app.localized[name] then name = app.localized[name] end
  return label, name, armorWeight;
end
app.GetExSetInfoFromSetID = GetExSetInfoFromSetID;

