local function GenerateSetInfoFromSetID(longSetID, isWeapon)
  --if not isWeapon then
    local expac = floor(longSetID/app.expandedID);
    local setID = mod(longSetID,app.expandedID);
    
    local callback = app.GenerateSetInfo[expac]
    if type(callback) == "function" then callback(setID) end
  --else
  --  local expac = floor(longSetID/1000);
  --  local setID = mod(longSetID,1000);
  --  
  --end
  
end
app.GenerateSetInfoFromSetID = GenerateSetInfoFromSetID;

----
--
----
local NOT_REMIX = "NOT_REMIX";
local IS_REMIX = "IS_REMIX";
local IS_REMIX_LEGION = "IS_REMIX_LEGION";
local function GetFormattedLabel(label)
  if not label then return "" end
  
  if label == IS_REMIX then
    return app.GetLocalizedString("MoPRemixExclusive");
  elseif label == IS_REMIX_LEGION then
    return app.GetLocalizedString("LegRemixExclusive");
  elseif app.localized[label] then
    return app.localized[label]; --moving the description to the previously unused 5th slot
  end
  
  local labelTable = {}
  for out in gmatch(label,"[^:]+") do
    tinsert(labelTable,out);
  end
  if labelTable[1] == "a" then
    local ach = GetAchievementLink(labelTable[2]);-- print(labelTable[2],"  ",GetAchievementLink(labelTable[2]))
    return app.GetLocalizedString("Achievement:")..GetAchievementLink(labelTable[2]);
  elseif labelTable[1] == "d" then
    local tooltip = C_TooltipInfo.GetHyperlink(format("unit:Creature-0-0-0-0-%d-0", labelTable[2]));
    if tooltip then
      return app.GetLocalizedString("SL_WepSetNote48").."\124cffffff00"..tooltip.lines[1].leftText.."\124r";
    else
      return {1,label};
    end
  elseif labelTable[1] == "i" then
    local itemID = labelTable[2];
    local itemLink = select(2,C_Item.GetItemInfo(itemID));
    if itemLink then
      return app.GetLocalizedString("Item:")..itemLink;
    else
      return {itemID,label};
      ----0 Poor, 1 Common, 2 Uncommon, 3 Rare, 4 Epic, 5 Legendary, 6 Artifact, 7 Heirloom, 8 WoW Token
      --local _,_,_,color = C_Item.GetItemQualityColor(labelTable[3]);
      --local retLabel = app.GetLocalizedString("Item:").."\124c"..color.."\124Hitem:"..itemID;
      --if labelTable[5] then
      --  retLabel = retLabel..":::::::::::"..labelTable[5];
      --end
      --retLabel = retLabel.."\124h["..labelTable[4].."]\124h\124r"
      --return retLabel, itemID;
    end
  elseif labelTable[1] == "l" then
    return app.GetLocalizedString("LootedFrom")..labelTable[2];
  elseif labelTable[1] == "li" then
    local itemID = labelTable[2];
    local itemLink = select(2,C_Item.GetItemInfo(itemID));
    if itemLink then
      return app.GetLocalizedString("LootedFrom")..itemLink;
    else
      return {itemID,label};
    end
  elseif labelTable[1] == "q" then
    local str = app.GetLocalizedString("Quest:")
    for i = 2,#labelTable do
      local questID = labelTable[i];
      local questName = QuestUtils_GetQuestName(questID);
      if questName == "" then return {questID,label} end
      str = str.."\124cffffff00\124Hquest:"..questID.."\124h["..questName.."]\124h\124r ";
    end
    return str;
  elseif labelTable[1] == "r" then
    local tier = tonumber(labelTable[2]);
    local faction = C_Reputation.GetFactionDataByID(labelTable[3]);
    if not faction then faction = C_MajorFactions.GetMajorFactionData(labelTable[3]); end
    local factionName = faction.name;
    local repStr = "";
    if tier == 1 then repStr = app.GetLocalizedString("FriendlyWith")
    elseif tier == 2 then repStr = app.GetLocalizedString("HonoredWith")
    elseif tier == 3 then repStr = app.GetLocalizedString("ReveredWith")
    elseif tier == 4 then repStr = app.GetLocalizedString("ExaltedWith")
    elseif tier == 5 then repStr = app.GetLocalizedString("ParagonBox")
    elseif tier == 6 then repStr = app.GetLocalizedString("RenownLevel")
    elseif tier == 7 then repStr = app.GetLocalizedString("GuestWith")
    elseif tier == 8 then repStr = app.GetLocalizedString("TrendsetterWith")
    elseif tier == 9 then repStr = app.GetLocalizedString("LuminaryWith")
    end
    if tier ~= 6 then
      return repStr.."\124cffffff00"..factionName.."\124r";
    else
      return "\124cffffff00"..factionName.."\124r"..repStr..labelTable[4];
    end
  elseif labelTable[1] == "v" then
    local tooltip = C_TooltipInfo.GetHyperlink(format("unit:Creature-0-0-0-0-%d-0", labelTable[2]));
    if tooltip then
      return app.GetLocalizedString("Vendor").."\124cffffff00"..tooltip.lines[1].leftText.."\124r";
    else
      return {1,label};
    end
  elseif labelTable[1] == "e" then
    local p2 = labelTable[3] and " "..app.GetLocalizedString(labelTable[3]) or "";
    return app.GetLocalizedString("Event").."\124cffffff00"..app.GetLocalizedString(labelTable[2])..p2.."\124r";
  elseif labelTable[1] == "wb" then
    local tooltip = C_TooltipInfo.GetHyperlink(format("unit:Creature-0-0-0-0-%d-0", labelTable[2]));
    if tooltip then
      return app.GetLocalizedString("WorldBoss").."\124cffffff00"..tooltip.lines[1].leftText.."\124r";
    else
      return {1,label};
    end
  elseif labelTable[1] == "du" then
    EJ_SelectInstance(labelTable[2]);
    local dungeonLink = select(8, EJ_GetInstanceInfo(1304))
    return app.GetLocalizedString("Dungeon")..": "..dungeonLink;--\124cff66bbff\124Hjournal:0:"..labelTable[2]..":1\124h["..dungeonName.."]\124h\124r";
  else
    return label;
  end
end
