----
--
----
--local tooltipLines = {}
--local tooltipLineUsage = 0;

local function AddSetInfoToItemTooltip(tooltip, data, macroID)
  if not ExS_Settings.showTooltipSetInfo then return end;
  
  local _,id1,id2 = TooltipUtil.GetDisplayedItem(tooltip);
  local id = id1 or macroID;
  if not id then return; end
  
  --if tooltipLines[id] then
  --  for i=1,#tooltipLines[id] do
  --    tooltip:AddDoubleLine(" ",tooltipLines[id][i]);
  --  end
  --  return;
  --end
  
  if tooltip.ExS_itemID == id and tooltip.ExS_prevTooltip then
    for i=1,#tooltip.ExS_prevTooltip do
      tooltip:AddDoubleLine(" ",tooltip.ExS_prevTooltip[i]);
    end
    return;
  end
  tooltip.ExS_itemID = id;
  tooltip.ExS_prevTooltip = {};
  --tooltipLineUsage = tooltipLineUsage + 1;
  --if tooltipLineUsage > 5 then
  --  tooltipLines = {};
  --end
  --tooltipLines[id] = {};
  
  if select(2,C_Item.GetItemInfoInstant(id)) == "Recipe" then
    for a,b in pairs(C_TooltipInfo.GetItemByID(id2).lines) do
      if b.tooltipID then
        id = b.tooltipID;
        break;
      end
    end
  end
  
  if not C_Item.IsDressableItemByID(id) then return end
  
  --Get the appID from the tooltip itemLink
  local appID, sourceID = C_TransmogCollection.GetItemInfo(id)
  --Get the appID from the tooltip itemID
  if not appID then appID = C_TransmogCollection.GetItemInfo(id2) end
  --Get the appID by equipping it to a hidden model and then asking the model what its wearing
  if not appID then
    local slots = invSlots[select(4,C_Item.GetItemInfoInstant(id))]
    if slots == nil then return end
    hiddenModel:SetUnit("player")
    hiddenModel:Undress()
    for i,slot in pairs(slots) do
      hiddenModel:UndressSlot(slot)
      hiddenModel:TryOn(id, slot);
      local slotInfo = hiddenModel:GetItemTransmogInfo(slot);
      if slotInfo and slotInfo.appearanceID and slotInfo.appearanceID ~= 0 then
        appID = AppID(slotInfo.appearanceID)
        break;
      end
    end
  end
  --If we still don't have an appID then bail
  if not appID then return; end
  
  local sets, isArmor = FindSetIDByAppID(appID)
  
  if not isArmor and ExS_Settings.hideWeaponsTab then return; end
  
  if appID and sets then
    for i=1,#sets do
      if not isArmor then
        local expac = floor(sets[i]/1000);
        local setID = mod(sets[i],1000);
        
        local callback = app.GetExpacWepSetNameBySetID[expac]
        local label, name
        if type(callback) == "function" then label, name = callback(setID) end
        if not label then label = tostring(sets[i]) end
        if not name then name = "" end
        if app.localized[label] then label = app.localized[label] end
        if app.localized[name] then name = app.localized[name] end
        
        local cc = "";
        if app.wepSetsReady then
          local col, tot = app.GetWepSetCount(sets[i]);
          local count = " ("..col.."/"..tot..")";
          local color;
          if col == tot then
            color = app.colors.GREEN_LIST_COLOR;
          elseif col > 0 then
            color = app.colors.YELLOW_FONT_COLOR;
          else
            color = GRAY_FONT_COLOR;
          end
          cc = WrapTextInColor(count,color);
        end
        
        if app.devMode then cc = cc.." "..sets[i] end
        
        --tooltipLines[id][i] = app.ColorString(app.GetLocalizedString("PartOfWeaponSet")..": ",225,110,225)..app.ColorString(label.." => "..name..cc,95,195,230)
        --tooltip:AddDoubleLine(" ",tooltipLines[id][i]);
        
      --AddRightSideLine(tooltip, tooltipLines[id][i]);
        tooltip.ExS_prevTooltip[i] = app.ColorString(app.GetLocalizedString("PartOfWeaponSet")..": ",225,110,225)..app.ColorString(label.." => "..name..cc,95,195,230)
        tooltip:AddDoubleLine(" ",tooltip.ExS_prevTooltip[i]);
      else
        local label, name, armorWeight;
        if sets[i] > app.expandedID then
          label, name, armorWeight = GetExSetInfoFromSetID(sets[i]);
        else
          local setInfo = C_TransmogSets.GetSetInfo(sets[i]);
          if setInfo == nil then return end
          
          if app.altLabelDB[setInfo.expansionID+1] and app.altLabelDB[setInfo.expansionID+1][setInfo.setID] then
            name = app.altLabelDB[setInfo.expansionID+1][setInfo.setID];
          elseif setInfo.description then
            name = setInfo.description;
          else
            name = setInfo.name;
          end
          if app.setsCustomLabels[sets[i]] then
            label = app.setsCustomLabels[sets[i]];
          elseif app.altLabelDB[setInfo.expansionID] and app.altLabelDB[setInfo.expansionID][sets[i]] then
            label = app.altLabelDB[setInfo.expansionID][sets[i]];
          else
            label = setInfo.label;
          end
          
          if app.setsSetClassMask[sets[i]] then
            armorWeight = app.setsSetClassMask[sets[i]];
          else
            armorWeight = setInfo.classMask;
          end
        end
        
        local cc = "";
        if app.SetsFrame and type(app.SetsFrame.GetSetSourceCounts) == "function" then
          local col, tot = app.SetsFrame.GetSetSourceCounts(sets[i]);
          local count = " ("..col.."/"..tot..")";
          
          local color;
          if col == tot then
            color = app.colors.GREEN_LIST_COLOR;
          elseif col > 0 then
            color = app.colors.YELLOW_FONT_COLOR;
          else
            color = GRAY_FONT_COLOR;
          end
          cc = WrapTextInColor(count,color);
        end
        
        if app.devMode then cc = cc.." "..sets[i] end
        
        local armorName = app.GetColoredClassNameString(armorWeight,true);
        if armorName ~= "" then
          armorName = " ("..armorName..")";
        end
        if label == nil then label = "" else label = label.." => " end
        --tooltipLines[id][i] = app.ColorString(app.GetLocalizedString("PartOfArmorSet")..": ",225,110,225)..app.ColorString(label..name..armorName..cc,95,195,230)
        --tooltip:AddDoubleLine(" ",tooltipLines[id][i]);
        
      --AddRightSideLine(tooltip, tooltipLines[id][i]);
        tooltip.ExS_prevTooltip[i] = app.ColorString(app.GetLocalizedString("PartOfArmorSet")..": ",225,110,225)..app.ColorString(label..name..armorName..cc,95,195,230)
        tooltip:AddDoubleLine(" ",tooltip.ExS_prevTooltip[i]);
      end
    end
  end
  
  if app.devMode then
    --if tooltipLines[id] then
    if not id then id = "nil" end
    --tooltipLines[id][#tooltipLines[id] + 1] = "SourceID: "..sourceID
    --tooltip:AddDoubleLine(" ",tooltipLines[id][#tooltipLines[id]]); 
    tooltip.ExS_prevTooltip[#tooltip.ExS_prevTooltip + 1] = "ItemID: "..id
    tooltip:AddDoubleLine(" ",tooltip.ExS_prevTooltip[#tooltip.ExS_prevTooltip]); 
    if not sourceID then sourceID = "nil" end
    --tooltipLines[id][#tooltipLines[id] + 1] = "SourceID: "..sourceID
    --tooltip:AddDoubleLine(" ",tooltipLines[id][#tooltipLines[id]]); 
    tooltip.ExS_prevTooltip[#tooltip.ExS_prevTooltip + 1] = "SourceID: "..sourceID
    tooltip:AddDoubleLine(" ",tooltip.ExS_prevTooltip[#tooltip.ExS_prevTooltip]); 
    if not appID then appID = "nil" end
    --tooltipLines[id][#tooltipLines[id] + 1] = "AppID: "..appID
    --tooltip:AddDoubleLine(" ",tooltipLines[id][#tooltipLines[id]]); 
    tooltip.ExS_prevTooltip[#tooltip.ExS_prevTooltip + 1] = "AppID: "..appID
    tooltip:AddDoubleLine(" ",tooltip.ExS_prevTooltip[#tooltip.ExS_prevTooltip]);
    --end
  end
  
  tooltip:Show();
end
TooltipDataProcessor.AddTooltipPostCall(Enum.TooltipDataType.Item, AddSetInfoToItemTooltip);

----
--Adding Armor DB Lines
--1) setID
--2) name
--3) desc (var drop down name)
--4) Note
--5) Label
--6) classMask
--7) patchID
--8) sources
--9) reqFaction (also expacID for the misc file)
--10) 1 (or true) = NoLongerObtainable
--    2 = NeverObtainable
--11) raceID
--12) partial Set
--13) 1 = trading post
--    2 = remix flag
--    3 = shop
--    4 = pvp
--14) holiday
----
local function AddDBLineToTables(dbL, expacID, isTransmogrifier)
  local data = {};
  data.setID = dbL[1];
  data.uiOrder = data.setID;
  data.name = app.GetLocalizedString(dbL[2])
  data.description = app.GetLocalizedString(dbL[3])
  data.note--[[, data.itemID]] = GetFormattedLabel(dbL[4])
  data.label = app.GetLocalizedString(dbL[5])
  data.classMask = dbL[6];
  data.patchID = dbL[7];
  if expacID == 100 then
    data.expansionID = dbL[9];
  else
    data.requiredFaction = dbL[9];
    data.expansionID = expacID;
  end
  data.favorite = false;
  if dbL[10] == 2 then
    data.neverObtainable = true;
  elseif dbL[10] then
    data.noLongerObtainable = true;
  end
  data.raceID = dbL[11];
  data.incomplete = dbL[12];
  if dbL[13] == 1 then
    data.tp = true;
  elseif dbL[13] == 2 then
    data.isRemix = data.expansionID+1;
    if data.expansionID == 4 or data.expansionID == 9 then data.noLongerObtainable = true; end
  elseif dbL[13] == 3 then
    data.shop = true;
  elseif dbL[13] == 4 then
    data.pvp = 1;
  end
  data.holiday = dbL[14];
  
  data.sources = {};
  for j=1,#dbL[8] do 
    if type(dbL[8][j]) == "table" then
      if not data.altSources then data.altSources = {}; data.altSourceNumbers = {}; end
      --local isKnown = false;
      --for a,b in pairs(C_TransmogCollection.GetAllAppearanceSources(app.AppID(dbL[8][j][1], data.setID, true))) do
      --  if C_TransmogCollection.PlayerKnowsSource(b) then
      --    isKnown = true;
      --    break;
      --  end
      --end
      data.sources[dbL[8][j][1]] = -1;
      data.altSources[dbL[8][j][1]] = {}
      for k=1,#dbL[8][j] do
        app.AppID(dbL[8][j][k], data.setID, true)
        tinsert(data.altSources[dbL[8][j][1]], dbL[8][j][k]);
      end
      data.altSourceNumbers[dbL[8][j][1]] = 1;
    else
      --local isKnown = false;
      --for a,b in pairs(C_TransmogCollection.GetAllAppearanceSources(app.AppID(dbL[8][j], data.setID, true))) do
      --  if C_TransmogCollection.PlayerKnowsSource(b) then
      --    isKnown = true;
      --    break;
      --  end
      --end
      data.sources[dbL[8][j]] = -1;
    end
  end
  
  --if notUsed then
  --  app.AddSetToNotUsedTable(data);
  --else
  if not isTransmogrifier then
    app.SetsFrame.AddSetToTables(data);
  else
    app.UseSetForTransmogrify(data);
  end
  --end
end
app.AddDBLineToTables = AddDBLineToTables;

