----
--Adding Weapon DB Lines
--1) setID
--2) name
--3) label
--4) difficulty (variant name/desc)
--5) patchID
--6) top-line note (gets pushed to each individual wep), -1 sets note to never obtainable, -2 sets note as trading post
--7) bottom-line note (gets pushed to each individual wep)(bottom line doesn't allow -1,-2 as above)
--8) sources
--  --1)wepType
--  --2)sourceID
--  --3)top note line, -1 sets note to never obtainable, -2 sets note as trading post
--  --4)top note line, (bottom line doesn't allow -1,-2 as above)
--9) 1 = PvP
--   2 = tp
--   3 = raid
--   4 = shop
--10) 1 = no longer obtainable
--    2 = limitedTimeSet
--11) string = reqFaction
--    number = classMask
--12) Remix
----
local function AddWepDBLineToTables(dbL, expacID)
  local data = {};
  data.setID = dbL[1];
  data.name = app.GetLocalizedString(dbL[2])
  data.label = app.GetLocalizedString(dbL[3])
  data.difficulty = app.GetLocalizedString(dbL[4])
  data.patchID = dbL[5];
  data.sources = {};
  if dbL[9] then
    if dbL[9] == 1 then
      data.isPvP = true;
    elseif dbL[9] == 2 then
      data.tp = true;
      if dbL[6] == nil then
        dbL[6] = "Trading Post";
      elseif dbL[7] == nil then
        dbL[7] = "Trading Post";
      end
    elseif dbL[9] == 3 then
      data.isRaid = true;
    elseif dbL[9] == 4 then
      data.shop = true;
    end
  end
  if dbL[10] == 1 then
    data.noLongerObtainable = true;
  elseif dbL[10] == 2 then
    data.limitedTimeSet = true;
  end
  data.favorite = false;
  data.expansionID = expacID;
  
  if type(dbL[11]) == "string" then
    data.requiredFaction = dbL[11];
  else
    data.classMask = dbL[11];
  end
  if dbL[12] then
    data.isRemix = expacID;
    data.isAllRemix = true;
  end
  --if dbL[12] == IS_REMIX then
  --  data.isRemix = true;
  --  data.isAllRemix = true;
  --end
  
  
  data.sources = dbL[8];
  for j=#data.sources,1,-1 do
    local appID = app.AppID(data.sources[j][2], data.setID, false);
    
    local s = C_TransmogCollection.GetAllAppearanceSources(appID);
    
    local skipSource = false;
    if data.sources[j][3] == -1 then
      if ExS_Settings.hideNeverObtainable then skipSource = true; end
      
      if app.devMode and #s > 1 then
        print("New source for unobtainable weapon! Set: ",data.name," Source: ",data.sources[j][1],", ",data.sources[j][2]);
        for a,b in pairs(s) do print(a,"  ",b) end
      end
    end
    
    if not skipSource then        
      local isCollected = false;
      for i=1,#s do
        if C_TransmogCollection.GetSourceInfo(s[i]).isCollected then
          isCollected = true;
          break;
        end
      end
      
      if not data.icon then
        data.icon = C_TransmogCollection.GetSourceIcon(data.sources[j][2])
      end
      
      --Remix Section
      if data.sources[j][3] == IS_REMIX then
        if not data.isRemix then
          data.isRemix = 5;
        end
      elseif data.sources[j][3] == IS_REMIX_LEGION then
        if not data.isRemix then
          data.isRemix = 7;
        end
      end
      
      if (dbL[12] == IS_REMIX or dbL[12] == IS_REMIX_LEGION) and data.sources[j][3] ~= NOT_REMIX then
        if not data.sources[j][3] and not dbL[5] then
          data.sources[j][3] = dbL[12];
        elseif not data.sources[j][4] and not dbL[6] then
          data.sources[j][4] = dbL[12];
        end
      end
      if data.sources[j][3] == NOT_REMIX then
        data.sources[j][3] = nil;
      end
      --End Remix Section
      
      if not data.sources[j][3] and dbL[6] then data.sources[j][3] = dbL[6]; end
      data.sources[j][5], data.sources[j][7] = GetFormattedLabel(data.sources[j][3]);
      if not data.sources[j][4] and dbL[7] then data.sources[j][4] = dbL[7]; end
      data.sources[j][6], data.sources[j][8] = GetFormattedLabel(data.sources[j][4]);
      
      data.sources[j][3] = isCollected;
      data.sources[j][4] = appID;
    else
      tremove(data.sources,j);
    end
  end
  
  if #data.sources > 0 then
    app.AddWeaponSetToTables(data);
  end
end
app.AddWepDBLineToTables = AddWepDBLineToTables;

